import { writeFile } from 'node:fs/promises'
import { compileRegistry } from './registry-compile.mjs'

const artifact = await compileRegistry()
await writeFile(new URL('../src/lib/registry-artifact.mjs', import.meta.url),
  '// Generated by npm run ledger:compile from contracts/ThreatRegistry.sol.\n' +
  `export const REGISTRY_ARTIFACT = ${JSON.stringify(artifact, null, 2)}\n`)
console.log('Registry artifact compiled.')
